// Simple Neon Reflex game targeting <canvas id="game"></canvas>
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // no canvas found
  const ctx = canvas.getContext('2d');
  const W = (canvas.width = canvas.offsetWidth || 400);
  const H = (canvas.height = canvas.offsetHeight || 300);

  const PLAYER_SIZE = 20;
  const LANE_Y = [H * 0.25, H * 0.75]; // two lanes (up/down)
  let player = { x: 50, y: LANE_Y[0], lane: 0 };

  const obstacles = [];
  const OBSTACLE_W = 30;
  const OBSTACLE_H = H * 0.4;
  let speed = 2;
  let spawnTimer = 0;
  let score = 0;
  let running = true;

  const toggleLane = () => {
    player.lane = 1 - player.lane;
    player.y = LANE_Y[player.lane];
  };
  window.addEventListener('click', toggleLane);
  window.addEventListener('keydown', (e) => { if (e.code === 'Space') toggleLane(); });

  const drawNeon = (x, y, w, h, color) => {
    ctx.fillStyle = color;
    ctx.shadowColor = color;
    ctx.shadowBlur = 10;
    ctx.fillRect(x, y, w, h);
    ctx.shadowBlur = 0;
  };

  function spawnObstacle() {
    const top = Math.random() < 0.5; // from top or bottom
    const y = top ? 0 : H - OBSTACLE_H;
    obstacles.push({ x: W, y, w: OBSTACLE_W, h: OBSTACLE_H });
  }

  function update(dt) {
    // move obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= speed;
      // collision
      if (
        player.x < o.x + o.w &&
        player.x + PLAYER_SIZE > o.x &&
        player.y < o.y + o.h &&
        player.y + PLAYER_SIZE > o.y
      ) {
        running = false;
      }
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }
    // spawn logic
    spawnTimer -= dt;
    if (spawnTimer <= 0) {
      spawnObstacle();
      spawnTimer = 1500 / speed; // faster spawns as speed rises
    }
    // increase difficulty
    speed += 0.001;
    score += dt * 0.001;
  }

  function render() {
    ctx.clearRect(0, 0, W, H);
    // neon tunnel background
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, W, H);
    // player
    drawNeon(player.x, player.y, PLAYER_SIZE, PLAYER_SIZE, '#0ff');
    // obstacles
    obstacles.forEach(o => drawNeon(o.x, o.y, o.w, o.h, '#f0f'));
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
    if (!running) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#f88';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  }

  let last = performance.now();
  function loop(now) {
    const dt = now - last;
    last = now;
    if (running) update(dt);
    render();
    if (running) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
